import type { Plugin, PluginListenerHandle } from '@capacitor/core';

export interface AnalysisResult {
  count: number;
  sum: number;
  mean: number;
  min: number;
  max: number;
  stdDev: number;
}

export interface RunningTotalResult {
  total: number;
}

export interface AnalysisCompleteEvent {
  sequence: number;
  mean: number;
}

export interface MetricsAnalyzerPlugin extends Plugin {
  analyze(options: { values: number[] }): Promise<AnalysisResult>;
  getRunningTotal(): Promise<RunningTotalResult>;
  addListener(
    eventName: 'analysisComplete',
    listenerFunc: (event: AnalysisCompleteEvent) => void,
  ): Promise<PluginListenerHandle>;
}

import { WebPlugin } from '@capacitor/core';
import type { MetricsAnalyzerPlugin, AnalysisResult, RunningTotalResult } from './definitions';

export class MetricsAnalyzerWeb extends WebPlugin implements MetricsAnalyzerPlugin {
  private totalAnalyses = 0;

  constructor() {
    super({
      name: 'MetricsAnalyzer',
      platforms: ['web'],
    });
  }

  async analyze(options: { values: number[] }): Promise<AnalysisResult> {
    this.totalAnalyses++;
    const { values } = options;

    if (!values || values.length === 0) {
      const result: AnalysisResult = {
        count: 0,
        sum: 0,
        mean: 0,
        min: 0,
        max: 0,
        stdDev: 0,
      };

      this.notifyListeners('analysisComplete', {
        sequence: this.totalAnalyses,
        mean: 0,
      });

      return result;
    }

    const count = values.length;
    let sum = 0;
    let min = values[0];
    let max = values[0];

    for (const val of values) {
      sum += val;
      if (val < min) min = val;
      if (val > max) max = val;
    }

    const mean = sum / count;

    let sumSqDev = 0;
    for (const val of values) {
      sumSqDev += (val - mean) ** 2;
    }
    const variance = sumSqDev / count;
    const stdDev = Math.sqrt(variance);

    const result: AnalysisResult = {
      count,
      sum,
      mean,
      min,
      max,
      stdDev,
    };

    this.notifyListeners('analysisComplete', {
      sequence: this.totalAnalyses,
      mean,
    });

    return result;
  }

  async getRunningTotal(): Promise<RunningTotalResult> {
    return {
      total: this.totalAnalyses,
    };
  }
}

import { registerPlugin } from '@capacitor/core';
import type { MetricsAnalyzerPlugin } from './definitions';

const MetricsAnalyzer = registerPlugin<MetricsAnalyzerPlugin>('MetricsAnalyzer', {
  web: () => import('./web').then(m => new m.MetricsAnalyzerWeb()),
});

export * from './definitions';
export { MetricsAnalyzer };

import { MetricsAnalyzer } from './index';
import type { AnalysisCompleteEvent } from './definitions';

declare global {
  interface Window {
    MetricsAnalyzer: typeof MetricsAnalyzer;
    __analysisEvents: AnalysisCompleteEvent[];
  }
}

// Expose the plugin and events array on window
window.MetricsAnalyzer = MetricsAnalyzer;
window.__analysisEvents = [];

// Listen for the analysisComplete event
MetricsAnalyzer.addListener('analysisComplete', (event) => {
  window.__analysisEvents.push(event);
  const eventCountEl = document.getElementById('event-count');
  if (eventCountEl) {
    eventCountEl.textContent = String(window.__analysisEvents.length);
  }
});

// Wrap analyze to update the DOM with the most recent analysis result
const originalAnalyze = MetricsAnalyzer.analyze.bind(MetricsAnalyzer);
MetricsAnalyzer.analyze = async (options) => {
  const result = await originalAnalyze(options);
  const resultEl = document.getElementById('result');
  if (resultEl) {
    resultEl.textContent = JSON.stringify(result, null, 2);
  }
  return result;
};

// Wire up the manual testing UI
document.addEventListener('DOMContentLoaded', () => {
  const analyzeBtn = document.getElementById('analyze-btn');
  const valuesInput = document.getElementById('values-input') as HTMLInputElement;

  if (analyzeBtn && valuesInput) {
    analyzeBtn.addEventListener('click', async () => {
      const text = valuesInput.value.trim();
      let values: number[] = [];
      if (text) {
        values = text
          .split(',')
          .map((v) => parseFloat(v.trim()))
          .filter((v) => !isNaN(v));
      }
      try {
        await MetricsAnalyzer.analyze({ values });
      } catch (err) {
        console.error('Analysis failed:', err);
      }
    });
  }
});
